api/src/routes/productos.js<pre><code>const router = require("express").Router();
const db = [];
router.get("/", (req, res) =&gt; res.json(db));
router.post("/", (req, res) =&gt; { db.push(req.body); res.status(201).json(req.body); });
router.delete("/:id", (req, res) =&gt; res.status(204).end());
module.exports = router;
</code></pre>

web/src/pages/Catalogo.jsx<pre><code>import { useEffect, useState } from "react";
import ProductCard from "../components/ProductCard";
export default function Catalogo() {
  const [productos, setProductos] = useState([]);
  useEffect(() =&gt; { fetch("/api/productos").then(r =&gt; r.json()).then(setProductos); }, []);
  return productos.map(p =&gt; &lt;ProductCard key={p.nombre} {...p} onAgregar={n =&gt; console.log(n)} /&gt;);
}
</code></pre>

web/src/components/ProductCard.jsx<pre><code>export default function ProductCard({ nombre, precio, onAgregar }) {
  return (
    &lt;div className="card"&gt;
      &lt;h3&gt;{nombre}&lt;/h3&gt;
      &lt;p&gt;${precio}&lt;/p&gt;
      &lt;button onClick={() =&gt; onAgregar(nombre)}&gt;Agregar&lt;/button&gt;
    &lt;/div&gt;
  );
}
</code></pre>
